body {
    background-color: #fefefe;
    font-family: Cairo,sans-serif;
    -webkit-font-smoothing: subpixel-antialiased;
    -webkit-text-stroke: 1px transparent
}

body,html {
    scroll-behavior: smooth;
    flex: 1;
    max-width: 100%!important
}

html {
    overflow-x: hidden
}

.grecaptcha-badge {
    display: none;
    visibility: hidden;
    opacity: 0
}

.ant-card,.ant-card-body {
    border-radius: 15px
}

.ant-select:not(.ant-select-customize-input) .ant-select-selector,.ant-input {
    border-radius: 10px
}

.ant-select-selector {
    height: 38px;
    align-items: center
}

.swal2-title p {
    font-size: 18px;
    color: var(--primary-color)
}

.swal2-icon {
    font-size: 12px
}

.swal2-container.swal2-backdrop-show,.swal2-container.swal2-noanimation {
    background: #162547b3!important
}

.text-color-gray {
    color: #8b9399
}

.color-primary {
    color: var(--primary-color)
}

.color-err {
    color: red
}

.label-color {
    color: #a8b1b8
}

.icon-color {
    color: #cdd7e4
}

.icon-color:hover {
    color: var(--primary-color)
}

.icon-color:focus {
    color: #cdd7e4
}

.color-gray {
    color: gray
}

.ant-modal.err-modal .ant-modal-content .ant-modal-confirm-title {
    color: #ff4d4f;
    font-weight: 600
}

.ant-modal.err-modal-non-medical .ant-modal-content .ant-modal-confirm-title {
    color: #6b6b6b;
    text-align: center;
    font-family: Cairo;
    font-size: 14px;
    font-style: normal;
    font-weight: 600!important;
    line-height: normal
}

.border-radius {
    border-radius: 10px
}

.advanced-search-icon-ui {
    position: absolute;
    top: 5px!important;
    left: 12px!important
}

.advanced-search-icon-ui .anticon-search,.advanced-search-custom-ui {
    color: var(--primary-color)
}

.advanced-search-clear-icon-ui {
    top: 5px!important;
    left: 35px!important
}

.advanced-search-clear-icon-ui .anticon-close-circle {
    color: var(--primary-color)
}

