body {
    font-family: Cairo,Tahoma,Arial,sans-serif
}

.App {
    position: relative;
    width: 100%;
    overflow: hidden;
    background-color: #fff
}

.App .nav-container {
    padding-top: 0
}

.app-header {
    position: fixed;
    top: 0;
    width: 100%;
    z-index: 999
}

.app-header .logo {
    float: right;
    position: relative;
    font-size: .9em;
    width: 120px;
    height: 50px
}

main {
    height: 100%;
    min-height: calc(100vh - 90px);
    overflow: hidden;
    position: relative;
    background-color: #fff
}

a {
    color: var(--primary-color);
    text-decoration: none
}

a:hover {
    color: var(--secondary-color)
}

.table>thead {
    vertical-align: middle
}

th {
    height: 44px;
    padding: 15px
}

header {
    background-color: #f1fffe;
    border-bottom: 2px solid var(--primary-color);
    padding: 5px 10px 10px 5px
}

.navbar-light .navbar-nav .nav-link,.navbar-nav .nav-link .home {
    color: #000
}

.navbar-nav .nav-link {
    font-weight: 700;
    color: #000
}

.navbar-light .navbar-toggler {
    border: 0!important;
    outline: 0!important
}

.alert {
    padding-bottom: 12px
}

.alert-mini {
    background: transparent;
    border: 0;
    color: red;
    margin: 0;
    font-size: 13px;
    padding: 0!important
}

.btn {
    font-size: .8rem
}

.form-login .btn-primary {
    transition: all .4s!important;
    background: #306db5!important;
    border-radius: 10px!important;
    font-size: .8rem!important;
    line-height: 1.5rem!important
}

.btn-primary:hover {
    background-color: var(--primary-color);
    color: #fff!important;
    border-color: var(--primary-color)!important;
    opacity: .9!important
}

.btn-refresh {
    font-size: 10px!important
}

.btn-outline-primary {
    color: var(--primary-color)!important;
    border-color: var(--primary-color)!important;
    padding-bottom: 8px!important
}

.btn-outline-primary:hover {
    color: #fff!important;
    background-color: var(--primary-color);
    border-color: var(--primary-color)
}

.btn-primary.disabled,.btn-primary:disabled {
    background-color: var(--primary-color)!important;
    border-color: var(--primary-color)!important
}

.btn-check:active+.btn-outline-primary,.btn-check:checked+.btn-outline-primary,.btn-outline-primary.active,.btn-outline-primary.dropdown-toggle.show,.btn-outline-primary:active {
    color: #fff!important;
    background-color: var(--primary-color)!important;
    border-color: var(--primary-color)!important;
    box-shadow: none
}

.form-check-input:checked {
    background-color: var(--primary-color)!important;
    border-color: var(--primary-color)!important
}

.btn-check:focus+.btn-primary,.btn-primary:focus {
    color: #fff!important;
    background-color: var(--primary-color)!important;
    border-color: var(--primary-color)!important;
    box-shadow: none!important
}

.btn-link.back {
    position: absolute;
    top: 4px;
    right: 14px;
    color: gray;
    text-decoration: none;
    font-weight: 400
}

.btn-link.back svg {
    line-height: 11px;
    margin-top: 7px;
    height: 10px;
    padding-left: 5px
}

.dark svg {
    color: #309104!important
}

img,svg {
    vertical-align: baseline
}

.alert {
    padding: .5rem 1rem
}

.max-400 {
    max-width: 400px;
    margin: 0 auto
}

.results-inquiery {
    background: #f7f7f7!important;
    padding: 10px!important;
    margin: 25px 1px 1px!important;
    border: 1px solid gainsboro!important
}

.results-inquiery>div {
    padding: 10px!important
}

.results-inquiery span {
    display: block;
    font-weight: 700;
    padding: 8px 0
}

.inner-page {
    margin-top: 50px;
    padding-top: 7%
}

.inner-page p {
    margin-top: 20px;
    margin-bottom: 20px;
    text-align: center
}

.modal-title {
    font-size: 1.2rem
}

.modal-sm .modal-header,.modal-sm .modal-footer {
    padding: 8px!important
}

.list_roles.modal-body {
    overflow-y: auto!important;
    max-height: 100%!important;
    height: calc(100vh - 190px)!important
}

.warp_sms {
    position: relative
}

.warp_sms .msg {
    font-size: 12px
}

footer {
    background: #f9f9f9;
    padding: 40px;
    margin-top: 50px
}

footer p {
    font-size: 15px;
    margin: 0
}

.logo-footer {
    width: 85px;
    float: right
}

.logo-lean {
    width: 93px!important;
    float: right!important;
    padding-right: 11px!important
}

footer .row {
    align-items: center!important
}

aside.ant-layout-sider.custom-sider::-webkit-scrollbar {
    display: none
}

@media(prefers-reduced-motion:no-preference) {
    .App-logo {
        animation: App-logo-spin infinite 20s linear
    }
}

.App-header {
    background-color: #282c34!important;
    min-height: 100vh!important;
    display: flex!important;
    flex-direction: column!important;
    align-items: center!important;
    justify-content: center!important;
    font-size: calc(10px + 2vmin)!important;
    color: #fff!important
}

.App-link {
    color: #61dafb!important
}

@keyframes App-logo-spin {
    0% {
        transform: rotate(0)
    }

    to {
        transform: rotate(360deg)
    }
}

@media(min-width: 52em) {
    .services ul li {
        width:23%
    }
}

.info-box {
    border-radius: 10px;
    border: 1px solid var(--Status-Info-Bg, #E4F1FF);
    background: #fff;
    box-shadow: 0 0 10px #3c75b91a
}

.documents-fill-alert-container {
    margin-bottom: 10px;
    padding: 0 15px 5px
}

.documents-fill-alert-container p {
    margin: 0!important
}

.alert-layout {
    display: flex;
    align-items: center;
    gap: 10px;
    flex: 1 0 0
}

.alert-font {
    color: var(--Text-Colors-Text-Color-1, #3A3A3A);
    font-family: Cairo;
    font-size: 12px;
    font-style: normal;
    font-weight: 600;
    line-height: normal;
    margin: 0!important
}

.documents-fill-text {
    color: #8b9399;
    font-size: 12px
}

.documents-fill-text-download {
    color: #8b9399;
    font-size: 12px;
    cursor: pointer;
    font-weight: 700;
    text-decoration: underline
