    flex-direction: row;
    margin-top: 10px;
    margin-bottom: 40px;
    padding-right: 25px
}

.clear-button {
    background: #fff;
    color: var(--primary-color);
    border-color: var(--primary-color)
}

.loading {
    position: absolute;
    width: 100%;
    height: 100%;
    background-color: #253d7608;
    z-index: 110;
    display: flex;
    justify-content: center;
    align-items: center;
    inset: 0;
    font-size: 35px
}

.overlay {
    background-color: #0003!important;
    box-shadow: 1px -6px 107px 5px #ffffffbf inset!important
}

.error-page {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
    height: calc(100vh - 40px);
    background-image: url(/assets/seha-logo-watermark-B8bOcw9T.svg);
    background-repeat: no-repeat;
    background-position: bottom left
}

.error-page .seha-logo,.error-page .error-img {
    margin-bottom: 60px
}

.error-page h1 {
    color: #416cad;
    font-weight: 700;
    font-size: 38px;
    margin-bottom: 60px
}

.error-page h4 {
    color: #3a3a3a;
    font-size: 22px;
    margin-bottom: 60px
}

.error-page .call-to-action-primary .btn {
    width: 280px;
    max-height: 60px;
    font-size: 22px
}

.error-page .call-to-action-primary .btn svg {
    width: 26px;
    height: 26px
}

.error-page~.footer {
    background-color: #1f2c55;
    color: #fff;
    text-align: center;
    line-height: 40px;
    font-size: 14px
}

.error-page~.footer .contact-col {
    display: flex;
    justify-content: center;
    gap: 15px
}

.error-page~.footer .contact-col .social-icons {
    display: flex;
    align-items: center;
    gap: 10px
}

.error-page~.footer .contact-col .email>a,.error-page~.footer .contact-col .phone>a {
    color: #fff;
    text-decoration: none
}

@media(max-width: 430px) {
    .error-page {
        transform:scale(.8);
        height: calc(100vh - 80px);
        background-size: contain;
        background-position: center
    }
}

@media(max-width: 375px) {
    .error-page {
        transform:scale(.6)
    }
}

@media(max-width: 280px) {
    .error-page {
        transform:scale(.6)
    }

    .error-page~.footer {
        overflow: hidden;
        font-size: 12px
    }
}

@media(max-height: 760px) {
    .error-page {
        transform:scale(.8)
    }
}

@media(max-height: 615px) {
    .error-page {
        transform:scale(.7)
    }
}

@media(max-height: 540px) {
    .error-page {
        transform:scale(.6)
    }
}

.notfound {
    display: flex;
    justify-content: center;
    align-content: center;
    align-items: center;
    text-align: center;
    height: 100vh;
    background-image: url(/assets/background-check-3-CmrCxDuL.svg)
}

.notfound h1 {
    color: var(--primary-color)
}

