.login-container {
    display: flex;
    height: 100vh;
    max-height: 100vh;
    width: 100%;
    position: relative;
    background: #f8f9fb;
    overflow: hidden;
    direction: rtl
}

.login-background {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 0
}

.login-background img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center
}

.login-content-wrapper {
    width: 100%;
    height: 100%;
    max-height: 100vh;
    position: relative;
    z-index: 1;
    box-shadow: 0 32px 32px #00000014;
    overflow: hidden
}

.login-content-wrapper .container-fluid {
    height: 100%;
    padding: 0
}

.login-content-wrapper .row {
    height: 100%;
    margin: 0
}

.form-section {
    background: #fff;
    border-radius: 8px;
    padding: 69px 82px 30px 32px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    height: 100%;
    max-height: 100vh;
    overflow-y: auto
}

.form-container {
    width: 720px;
    margin: 0 auto
}

.form-header {
    border-bottom: 1px dashed #dfe7f2;
    margin-bottom: 48px;
    padding: 0 36px
}

.login-title-section {
    text-align: right
}

.login-title-section h1 {
    font-family: Cairo,sans-serif;
    font-weight: 700;
    font-size: 16px;
    color: #306db5;
    margin: 0
}

.form-content {
    padding: 0 36px
}

.login-form {
    display: flex;
    flex-direction: column;
    gap: 20px
}

.input-field {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    width: 100%
}

.input-label {
    font-family: Cairo,sans-serif;
    font-weight: 500;
    font-size: 14px;
    color: #798ca1;
    margin-bottom: 4px;
    float: left;
    padding-left: 16px
}

.form-input {
    width: 100%;
    height: 40px;
    border: 1px solid #cbd7e4;
    border-radius: 8px;
    padding: 0 16px;
    font-family: Cairo,sans-serif;
    font-weight: 600;
    font-size: 14px;
    color: #cbd7e4;
    text-align: right;
    background: #fff
}

.form-input:focus {
    outline: none;
    border-color: #306db5;
    color: #333
}

.form-input.error {
    border-color: red
}

.form-input::placeholder {
    color: #cbd7e4
}

.login-button {
    width: 100%;
    height: 48px;
    background: #306db5;
    border: none;
    border-radius: 8px;
    color: #fff;
    font-family: Cairo,sans-serif;
    font-weight: 700;
    font-size: 14px;
    cursor: pointer;
    transition: all .3s ease
}

.login-button:hover:not(:disabled) {
    background: #1e4a7a
}

.login-button:disabled {
    opacity: .6;
    cursor: not-allowed
}

.forgot-password-section {
    display: flex;
    justify-content: center;
    margin-top: 4px
}

.forgot-password-link {
    display: flex;
    align-items: center;
    gap: 10px;
    text-decoration: none;
    color: #306db5;
    font-family: Cairo,sans-serif;
    font-size: 14px
}

.forgot-password-link .icon {
    width: 16px;
    height: 16px
}

.forgot-password-link .underline {
    text-decoration: underline;
    font-weight: 700
}

.divider {
    display: flex;
    align-items: center;
    gap: 5px;
    margin: 20px 0
}

.divider .divider-line {
    flex: 1;
    height: 1px;
    background: #cbd7e4
}

.divider .divider-text {
    font-family: Cairo,sans-serif;
    font-weight: 500;
    font-size: 14px;
    color: #798ca1;
    padding: 10px
}

.national-access-button {
    width: 100%
}

.national-access-link {
    display: block;
    width: 100%;
    border: 1px solid #306db5;
    border-radius: 6px;
    padding: 10px;
    text-decoration: none;
    background: #fff
}

.national-access-content {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
