}

.public-challenge-join .page-head .meta {
    width: 660px;
    height: 16px;
    display: flex;
    justify-content: space-between;
    gap: 8px;
    opacity: 1
}

.public-challenge-join .page-head .meta .meta-item {
    width: auto;
    height: 16px;
    display: inline-flex;
    align-items: center;
    justify-content: flex-start;
    gap: 8px;
    opacity: 1;
    border-radius: 4px;
    font-family: Cairo;
    font-weight: 400;
    font-style: normal;
    font-size: 12px;
    line-height: 100%;
    letter-spacing: 0;
    text-align: right;
    vertical-align: middle;
    color: #6b6b6b;
    white-space: nowrap
}

.public-challenge-join .page-head .meta .meta-item .value {
    color: #306db5;
    font-family: Cairo;
    font-weight: 400;
    font-style: normal;
    font-size: 12px;
    line-height: 100%;
    letter-spacing: 0;
    text-align: right;
    vertical-align: middle;
    margin-inline-start:6px;white-space: nowrap
}

.public-challenge-join .selection-summary {
    color: #6b6b6b;
    font-family: Cairo;
    font-weight: 600;
    font-size: 14px
}

.public-challenge-join .selection-summary .selection-pill {
    display: inline-flex;
    align-items: baseline;
    gap: 8px
}

.public-challenge-join .selection-summary .text {
    color: #6b6b6b
}

.public-challenge-join .selection-summary .count {
    color: var(--primary-color, #306DB5);
    font-weight: 700;
    font-size: 14px;
    line-height: 1
}

.public-challenge-join .max-limit-row {
    display: flex;
    justify-content: flex-end;
    align-items: center;
    width: 100%
}

.public-challenge-join .max-limit-note {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: #e6f1fb;
    color: #306db5;
    border-radius: 10px;
    padding: 8px 12px;
    font-weight: 700;
    font-size: 12px;
    white-space: nowrap
}

.public-challenge-join .max-limit-note .info-dot {
    width: 26px;
    height: 26px;
    border-radius: 50%;
    background: #306db5;
    display: inline-flex;
    align-items: center;
    justify-content: center
}

.public-challenge-join .max-limit-note .info-dot:before {
