    color: #bdbdbd;
    cursor: pointer;
    text-decoration: none
}

.public-challenge-join .search-input .advanced-search-clear-icon-ui {
    position: absolute;
    top: 50%;
    inset-inline-end: 36px;
    color: #cfcfe0;
